# 生产代码：用 raise...from 建立异常链
def fetch_user(user_id):
    try:
        return db.query(f"SELECT * FROM users WHERE id={user_id}")
    except DatabaseError as e:
        raise ServiceError(f"Cannot fetch user {user_id}") from e
# 测试：验证链是否正确建立
class TestFetchUser(unittest.TestCase):
    def test_db_error_wrapped_in_service_error(self):
        with patch('myapp.db.query') as mock_query:
            mock_query.side_effect = DatabaseError("connection lost")
            with self.assertRaises(ServiceError) as ctx:
                fetch_user(42)
        exc = ctx.exception
        self.assertIn("42", str(exc))
        self.assertIsInstance(exc.__cause__, DatabaseError)
        self.assertIn("connection lost", str(exc.__cause__))
```

`exc.__cause__` 就是 `from e` 那个 `e`。如果用 `raise X from None`，则 `__cause__` 为 `None`，`__suppress_context__` 为 `True`。

自定义异常往往携带结构化信息（属性），这些属性也是公开契约，需要测试。

```python
class InsufficientFundsError(ValueError):
    def __init__(self, balance, amount):
        self.balance = balance
        self.amount = amount
        self.shortfall = amount - balance
        super().__init__(
            f"Cannot charge {amount:.2f}: balance is only {balance:.2f}"
        )
class TestInsufficientFundsError(unittest.TestCase):
    def test_shortfall_calculation(self):
        exc = InsufficientFundsError(balance=10.0, amount=50.0)
        self.assertAlmostEqual(exc.shortfall, 40.0)
    def test_is_value_error_subclass(self):
        exc = InsufficientFundsError(10.0, 50.0)
        self.assertIsInstance(exc, ValueError)
    def test_raised_with_correct_attributes(self):
        account = BankAccount(balance=10.0)
        with self.assertRaises(InsufficientFundsError) as ctx:
            account.charge(50.0)
        self.assertAlmostEqual(ctx.exception.shortfall, 40.0)
```

`subTest` 是 `unittest` 内置的参数化方式，不需要安装任何库。

```python
class TestEmailValidator(unittest.TestCase):
    VALID_CASES = [
        "user@example.com",
        "user+tag@example.com",
        "user@sub.domain.co.uk",
    ]
    INVALID_CASES = [
        ("not-an-email",  "missing @"),
        ("@example.com",  "missing local part"),
        ("user@",         "missing domain"),
    ]
    def test_valid_emails_accepted(self):
        for email in self.VALID_CASES:
            with self.subTest(email=email):
                self.assertTrue(is_valid_email(email))
    def test_invalid_emails_rejected(self):
        for email, reason in self.INVALID_CASES:
            with self.subTest(email=email, reason=reason):
                self.assertFalse(is_valid_email(email))
```

`subTest` 的关键优势：**一个子测试失败，其余照样继续运行**，失败报告里会带上传给 `subTest` 的参数，方便定位。

第三方库 `parameterized` 提供 `@parameterized.expand`，把每组参数展开成独立的测试方法。

```python
from parameterized import parameterized
import unittest
class TestCalculator(unittest.TestCase):
    @parameterized.expand([
        ("add_positives",  2, 3,  5),
        ("add_negatives", -2, -3, -5),
        ("add_mixed",     -2, 3,  1),
        ("add_zeros",      0, 0,  0),
    ])
    def test_add(self, name, a, b, expected):
        # 展开为 test_add_0_add_positives、test_add_1_add_negatives 等
        self.assertEqual(a + b, expected)
    @parameterized.expand([
        (10, 0),
        (-5, 0),
    ])
    def test_divide_by_zero_raises(self, dividend, divisor):
        with self.assertRaises(ZeroDivisionError):
            divide(dividend, divisor)
```

展开后的方法名包含参数描述，`pytest` 或 `unittest` 运行器都能单独重跑某一个失败的子测试。

当不想引入第三方库时，可以用 `setattr` 在运行时把测试方法「挂」到类上。

```python
def generate_tests(test_class):
    test_cases = [
        ("zero",     0,    0),
        ("one",      1,    1),
        ("negative", -5,   5),
        ("large",    1000, 1000),
    ]
    def make_test(n, expected):
        def test(self):
            self.assertEqual(abs(n), expected)
        return test
    for name, n, expected in test_cases:
        setattr(test_class, f"test_abs_{name}", make_test(n, expected))
    return test_class
@generate_tests
class TestAbsoluteValue(unittest.TestCase):
    pass
# 自动生成：test_abs_zero, test_abs_one, test_abs_negative, test_abs_large
```

`make_test` 用闭包捕获 `n` 和 `expected`，避免循环变量被最后一次赋值覆盖的经典陷阱。
